insert into fcps_mcq_stage (id, subject_name, chapter_name, question, options, correct_answer, explanation) values
('b83e43a3-e03a-5510-bc69-8af618dfecf7'::uuid, 'Pathology (Paper 2)', 'Immunology and Genetics', 'Which cells mediate innate immunity?', '["Plasma cells","B lymphocytes","Memory cells","Macrophages and neutrophils","T lymphocytes"]'::jsonb, 'Macrophages and neutrophils', 'Macrophages and neutrophils are key cells of innate immunity, providing immediate non-specific defense.'),
('20f808d3-603d-57a4-843a-b647ebb6ca78'::uuid, 'Pathology (Paper 2)', 'Immunology and Genetics', 'Which cells mediate adaptive immunity?', '["Neutrophils","Macrophages","Dendritic cells","T and B lymphocytes","Natural killer cells"]'::jsonb, 'T and B lymphocytes', 'T and B lymphocytes are responsible for adaptive (specific) immunity with memory.'),
('b1114854-5930-552a-86a2-82795d49c50c'::uuid, 'Pathology (Paper 2)', 'Immunology and Genetics', 'What is the primary function of natural killer cells?', '["Antibody production clinical presentation","Antigen presentation clinical presentation","Allergic reactions clinical presentation","Phagocytosis clinical presentation","Killing virus-infected and tumor cells"]'::jsonb, 'Killing virus-infected and tumor cells', 'NK cells kill virus-infected and tumor cells without prior sensitization, part of innate immunity.'),
('c6f9d9a3-9f45-54a9-902e-327250531f14'::uuid, 'Pathology (Paper 2)', 'Immunology and Genetics', 'Regarding clinical scenarios, Which immunoglobulin is the most abundant in serum?', '["IgE","IgM","IgD","IgA","IgG"]'::jsonb, 'IgG', 'IgG constitutes about 75-80% of serum immunoglobulins and crosses the placenta.'),
('4b2bff64-0965-5907-8a86-069995e49a0d'::uuid, 'Pathology (Paper 2)', 'Immunology and Genetics', 'Which immunoglobulin is produced first in primary immune response?', '["IgD","IgM","IgG","IgA","IgE"]'::jsonb, 'IgM', 'IgM is the first antibody produced in primary immune response and is a marker of recent infection.'),
('081ddd84-4ccd-5008-a0b9-de94f7c7483d'::uuid, 'Pathology (Paper 2)', 'Immunology and Genetics', 'Which immunoglobulin is involved in allergies and parasitic infections?', '["IgG","IgD","IgE","IgM","IgA"]'::jsonb, 'IgE', 'IgE mediates type I hypersensitivity (allergies) and defense against helminths.'),
('59abc317-7cee-5de1-90cd-c2672d692e62'::uuid, 'Pathology (Paper 2)', 'Immunology and Genetics', 'In a surgical context, Which immunoglobulin crosses the placenta?', '["IgM","IgE","IgD","IgG","IgA"]'::jsonb, 'IgG', 'IgG is actively transported across the placenta via FcRn receptors, providing passive immunity to the fetus.'),
('81791d6c-c9cb-5606-857d-c85992b594af'::uuid, 'Pathology (Paper 2)', 'Immunology and Genetics', 'Secretory IgA is primarily found in:', '["Serum","Lymph","Mucosal secretions","Bone marrow","CSF"]'::jsonb, 'Mucosal secretions', 'Secretory IgA (sIgA) is found in mucosal secretions providing immune protection at mucosal surfaces.'),
('40bf90f4-33aa-57e0-874c-793e08f41f60'::uuid, 'Pathology (Paper 2)', 'Immunology and Genetics', 'The receptor for antigen on T cells is called:', '["Immunoglobulin","CD8","T-cell receptor","CD4","MHC molecule"]'::jsonb, 'T-cell receptor', 'TCR recognizes antigen presented by MHC molecules. It is associated with CD3 complex.'),
('040bc56a-b8c6-5912-bf0a-96347ead5bfb'::uuid, 'Pathology (Paper 2)', 'Immunology and Genetics', 'CD4+ T cells recognize antigen presented by:', '["Natural killer cells","MHC class II","MHC class I","CD8","B cells"]'::jsonb, 'MHC class II', 'CD4+ helper T cells recognize antigens presented on MHC class II molecules.'),
('90791491-fda7-51ce-b5c8-909ae242cc74'::uuid, 'Pathology (Paper 2)', 'Immunology and Genetics', 'CD8+ T cells recognize antigen presented by:', '["MHC class II","B cells","CD3","MHC class I","CD4"]'::jsonb, 'MHC class I', 'CD8+ cytotoxic T cells recognize antigens presented on MHC class I molecules.'),
('775c030a-b706-5468-8322-e6c22218303e'::uuid, 'Pathology (Paper 2)', 'Immunology and Genetics', 'Which cell presents antigen to CD4+ T cells?', '["Neutrophil","Antigen-presenting cell","Eosinophil","NK cell","Cytotoxic T cell"]'::jsonb, 'Antigen-presenting cell', 'APCs process and present antigen via MHC class II to CD4+ T cells.'),
('d3591533-262a-518b-bb4b-50036050b7e1'::uuid, 'Pathology (Paper 2)', 'Immunology and Genetics', 'The major histocompatibility complex (MHC) in humans is called:', '["HLA","KIR","Rh factor","Fc receptor","ABO blood group"]'::jsonb, 'HLA', 'HLA is the human MHC, located on chromosome 6, encoding MHC class I and II molecules.'),
('39da62dc-c289-5f5a-b946-da1619a7d3f2'::uuid, 'Pathology (Paper 2)', 'Immunology and Genetics', 'MHC class I molecules are expressed on:', '["Red blood cells","Only T cells","All nucleated cells","Only antigen-presenting cells","Only B cells"]'::jsonb, 'All nucleated cells', 'MHC class I is expressed on all nucleated cells. Red blood cells lack MHC class I.'),
('6ec0e61c-68e0-5cd9-8dab-23a30446d7d5'::uuid, 'Pathology (Paper 2)', 'Immunology and Genetics', 'MHC class II molecules are expressed on:', '["All nucleated cells","Antigen-presenting cells","Red blood cells","T cells only","Neutrophils only"]'::jsonb, 'Antigen-presenting cells', 'MHC class II is expressed on professional APCs: dendritic cells, macrophages, and B cells.'),
('7e790015-bc45-5848-b7cc-555abab66ae0'::uuid, 'Pathology (Paper 2)', 'Immunology and Genetics', 'Which cytokine is produced by Th1 cells?', '["IL-5","IL-4","IL-13","IL-10","IFN-gamma"]'::jsonb, 'IFN-gamma', 'Th1 cells produce IFN-gamma, activating macrophages and promoting cell-mediated immunity.'),
('106212ae-0bee-5113-9ce9-01a40359d707'::uuid, 'Pathology (Paper 2)', 'Immunology and Genetics', 'Which cytokine is produced by Th2 cells?', '["IL-4","IL-12","IL-2","IFN-gamma","TNF-beta"]'::jsonb, 'IL-4', 'Th2 cells produce IL-4, IL-5, and IL-13, promoting humoral immunity and allergic responses.'),
('a2f13a1b-23ae-5883-899a-e0cf174e8089'::uuid, 'Pathology (Paper 2)', 'Immunology and Genetics', 'Th17 cells produce which signature cytokine?', '["IL-4","IFN-gamma","IL-17","TGF-beta","IL-10"]'::jsonb, 'IL-17', 'Th17 cells produce IL-17, recruiting neutrophils and mediating autoimmune inflammation.'),
('9932e331-de20-5aba-ad18-409844179b74'::uuid, 'Pathology (Paper 2)', 'Immunology and Genetics', 'Which cytokine is the main activator of B cells?', '["IFN-gamma","IL-2","IL-4","IL-6","IL-10"]'::jsonb, 'IL-4', 'IL-4 from Th2 cells stimulates B cell proliferation and class switching to IgE and IgG1.'),
('90e93bc2-ed9b-5c25-8926-36e75a1f8372'::uuid, 'Pathology (Paper 2)', 'Immunology and Genetics', 'Regulatory T cells (Treg) express which marker?', '["CD19","CD56","CD4+CD25+FOXP3+","CD8","CD4"]'::jsonb, 'CD4+CD25+FOXP3+', 'Treg cells express CD4, CD25, and FOXP3 transcription factor, suppressing immune responses.'),
('ea8ea802-2ec5-5624-bc3c-3ad72259a53c'::uuid, 'Pathology (Paper 2)', 'Immunology and Genetics', 'The complement system is part of:', '["Memory response","Adaptive immunity","Humoral immunity only","Innate immunity","Cell-mediated immunity"]'::jsonb, 'Innate immunity', 'Complement is part of the innate immune system, providing rapid defense and bridging to adaptive immunity.'),
('cd6ec2ed-8151-5a1f-ad22-900e8dd2a5f6'::uuid, 'Pathology (Paper 2)', 'Immunology and Genetics', 'The classical complement pathway is activated by:', '["Properdin","Microbial surfaces","Antigen-antibody complexes","Factor B","Mannose-binding lectin"]'::jsonb, 'Antigen-antibody complexes', 'Classical pathway is activated by IgM or IgG bound to antigen, activating C1q.'),
('f986a2cb-04dc-539c-9c45-6d3b95de3249'::uuid, 'Pathology (Paper 2)', 'Immunology and Genetics', 'The alternative complement pathway is activated by:', '["Antibody binding","C4 binding protein","C1q","Microbial surfaces","Mannan-binding lectin"]'::jsonb, 'Microbial surfaces', 'Alternative pathway is activated directly by microbial surfaces without antibody.'),
('eeb85c73-f45f-5f8d-8b16-50589a0d0eb9'::uuid, 'Pathology (Paper 2)', 'Immunology and Genetics', 'The lectin complement pathway is activated by:', '["Mannose residues on microbes","Factor B","C1q","Factor D","Antibody"]'::jsonb, 'Mannose residues on microbes', 'Lectin pathway is activated when mannan-binding lectin (MBL) binds to mannose on microbes.'),
('042048ca-1b32-58bb-b45e-8ade94053a15'::uuid, 'Pathology (Paper 2)', 'Immunology and Genetics', 'Which complement component forms the membrane attack complex (MAC)?', '["C3a","C2a","C4a","C5b-C9","C3b"]'::jsonb, 'C5b-C9', 'C5b binds C6, C7, C8, and multiple C9 molecules forming the MAC that lyses cells.'),
('9ee22c90-9dff-5f4f-843a-a0c8329249b9'::uuid, 'Pathology (Paper 2)', 'Immunology and Genetics', 'Which complement fragment is the most potent anaphylatoxin?', '["C4b","C3b","C4a","C3a","C5a"]'::jsonb, 'C5a', 'C5a is the most potent anaphylatoxin, causing mast cell degranulation and neutrophil chemotaxis.'),
('f2ee6844-2eb0-5ebd-b7ab-224dd355bbb4'::uuid, 'Pathology (Paper 2)', 'Immunology and Genetics', 'C3b functions primarily as an:', '["Cytokine","Opsonin","Chemotactic factor","Vasodilator","Anaphylatoxin"]'::jsonb, 'Opsonin', 'C3b is the main opsonin, coating pathogens for phagocytosis via complement receptors.'),
('7710b3dc-bca4-517f-a8c3-26ba9186adff'::uuid, 'Pathology (Paper 2)', 'Immunology and Genetics', 'Which hereditary deficiency causes recurrent Neisseria infections?', '["C3 deficiency","C2 deficiency","C5-C9 (MAC) deficiency","C1 deficiency","C4 deficiency"]'::jsonb, 'C5-C9 (MAC) deficiency', 'MAC deficiency (C5-C9) predisposes to recurrent Neisseria meningitidis and gonorrhoeae infections.'),
('ebfce276-3ad4-50fe-b22b-195c1674b54c'::uuid, 'Pathology (Paper 2)', 'Immunology and Genetics', 'Which complement deficiency is most common?', '["C2 deficiency","Factor B deficiency","C3 deficiency","C4 deficiency","C1 deficiency"]'::jsonb, 'C2 deficiency', 'C2 deficiency is the most common complement deficiency, associated with SLE-like syndrome.'),
('abe78bc1-911c-5527-a91d-62455c2fb716'::uuid, 'Pathology (Paper 2)', 'Immunology and Genetics', 'What is the role of decay accelerating factor (DAF/CD55)?', '["Promotes MAC formation clinical presentation","Binds C1q clinical presentation","Inhibits complement activation on host cells","Activates complement clinical presentation","Enhances opsonization clinical presentation"]'::jsonb, 'Inhibits complement activation on host cells', 'DAF (CD55) protects host cells from complement-mediated damage by accelerating decay of C3 convertase.'),
('daec96b5-29db-5d38-a3fe-6dfa1db3c6da'::uuid, 'Pathology (Paper 2)', 'Immunology and Genetics', 'Which surface protein deficiency causes paroxysmal nocturnal hemoglobinuria (PNH)?', '["DAF (CD55) and CD59","CR1","C4b","C3b","CR3"]'::jsonb, 'DAF (CD55) and CD59', 'PNH results from deficiency of GPI-anchored proteins (CD55, CD59) on RBCs, leading to complement-mediated hemolysis.'),
('c7781ff3-e65d-5024-bd4d-15720af28bd0'::uuid, 'Pathology (Paper 2)', 'Immunology and Genetics', 'The primary lymphoid organs include:', '["MALT and tonsils","Peyer patches and appendix","Spleen and tonsils","Bone marrow and thymus","Lymph nodes and spleen"]'::jsonb, 'Bone marrow and thymus', 'Bone marrow (B cell maturation) and thymus (T cell maturation) are primary lymphoid organs.'),
('e433ecfb-5db8-5463-bbf4-c54c63867095'::uuid, 'Pathology (Paper 2)', 'Immunology and Genetics', 'Secondary lymphoid organs include:', '["Heart and lungs","Lymph nodes, spleen, MALT","Liver and kidney","Bone marrow and thymus","Brain and spinal cord"]'::jsonb, 'Lymph nodes, spleen, MALT', 'Secondary lymphoid organs include lymph nodes, spleen, and mucosa-associated lymphoid tissue (MALT).'),
('5beb73b4-eae4-59e5-b0ee-ffd448d51ef9'::uuid, 'Pathology (Paper 2)', 'Immunology and Genetics', 'T lymphocytes mature in which organ?', '["Spleen","Thymus","Lymph nodes","Peyer patches","Bone marrow"]'::jsonb, 'Thymus', 'T cell precursors migrate from bone marrow to the thymus for maturation.'),
('3c065504-f9eb-532b-9ec5-e17fa862d667'::uuid, 'Pathology (Paper 2)', 'Immunology and Genetics', 'B lymphocytes mature in which organ?', '["Bone marrow","Lymph nodes","Thymus","Spleen","Tonsils"]'::jsonb, 'Bone marrow', 'B cells mature in the bone marrow before migrating to peripheral lymphoid organs.'),
('e9f29d67-1d91-5635-95a7-6d60635b0f29'::uuid, 'Pathology (Paper 2)', 'Immunology and Genetics', 'Which cytokine is the main growth factor for T cells?', '["IFN-gamma","IL-6","IL-1","IL-4","IL-2"]'::jsonb, 'IL-2', 'IL-2 (T-cell growth factor) stimulates T cell proliferation after antigen activation.'),
('21b7c9f1-5843-565c-a952-0e799dc07758'::uuid, 'Pathology (Paper 2)', 'Immunology and Genetics', 'Which cytokine is produced by macrophages activating T cells?', '["IL-10","IL-4","TGF-beta","IL-1","IL-2"]'::jsonb, 'IL-1', 'IL-1 from macrophages provides co-stimulation for T cell activation.'),
('31292c8d-c8ff-5934-bcb9-52af0d83c500'::uuid, 'Pathology (Paper 2)', 'Immunology and Genetics', 'What is an epitope?', '["An MHC molecule","The antigen-binding site on antibody","A type of antibody","The specific part of antigen recognized by immune system","A cytokine receptor"]'::jsonb, 'The specific part of antigen recognized by immune system', 'An epitope is the specific molecular region of an antigen recognized by immune receptors.'),
('54a02f2b-eec4-50d4-afa4-5457811072cf'::uuid, 'Pathology (Paper 2)', 'Immunology and Genetics', 'Which cell type is the most potent antigen-presenting cell?', '["Neutrophil","Macrophage","Fibroblast","B cell","Dendritic cell"]'::jsonb, 'Dendritic cell', 'Dendritic cells are the most potent APCs, specialized for antigen capture and T cell activation.'),
('9f638159-f1c0-5a89-a477-d1916d691a76'::uuid, 'Pathology (Paper 2)', 'Immunology and Genetics', 'Clonal deletion of self-reactive T cells occurs in:', '["Thymus","Bone marrow","Spleen","Peripheral blood","Lymph nodes"]'::jsonb, 'Thymus', 'Negative selection in the thymus eliminates self-reactive T cells (central tolerance).'),
('4d5df86b-e5b9-5002-9a3b-9004666f99fe'::uuid, 'Pathology (Paper 2)', 'Immunology and Genetics', 'What is the function of CD40-CD40L interaction?', '["Complement activation","Phagocytosis","NK cell activation","T cell apoptosis","B cell activation and class switching"]'::jsonb, 'B cell activation and class switching', 'CD40L on T cells binds CD40 on B cells, essential for B cell activation, class switching, and germinal center formation.'),
('bf515eb7-e4e0-5c55-bb0d-1742444e4f49'::uuid, 'Pathology (Paper 2)', 'Immunology and Genetics', 'Which deficiency causes Hyper-IgM syndrome?', '["MHC deficiency","CD4 deficiency","IL-2 deficiency","CD8 deficiency","CD40L deficiency on T cells"]'::jsonb, 'CD40L deficiency on T cells', 'X-linked hyper-IgM syndrome is caused by CD40L (CD154) mutation, preventing class switching.'),
('cf750814-23bd-52b0-b440-d5bd713676f8'::uuid, 'Pathology (Paper 2)', 'Immunology and Genetics', 'What is the mechanism of action of cyclosporine?', '["Blocks IL-2 receptor","Depletes T cells","Inhibits calcineurin, blocking IL-2 transcription","Inhibits B cell proliferation","Blocks MHC expression"]'::jsonb, 'Inhibits calcineurin, blocking IL-2 transcription', 'Cyclosporine binds cyclophilin, inhibiting calcineurin and preventing IL-2 gene transcription in T cells.'),
('d46a93db-2756-5162-9054-65147bbb0fe3'::uuid, 'Pathology (Paper 2)', 'Immunology and Genetics', 'Tacrolimus (FK506) acts by:', '["Inhibiting complement","Same mechanism as cyclosporine via FKBP","Blocking antibody production","Blocking IL-2 receptor","Depleting lymphocytes"]'::jsonb, 'Same mechanism as cyclosporine via FKBP', 'Tacrolimus binds FKBP and inhibits calcineurin, similar to cyclosporine but more potent.'),
('acf71957-8d3c-5a30-8022-6c39c32bdc16'::uuid, 'Pathology (Paper 2)', 'Immunology and Genetics', 'Sirolimus (rapamycin) inhibits:', '["IL-2 receptor","CD28","CD4","mTOR","Calcineurin"]'::jsonb, 'mTOR', 'Sirolimus inhibits mTOR, blocking cell cycle progression in T cells.'),
('3f40684f-0025-5913-8e1a-88aa6275f8e6'::uuid, 'Pathology (Paper 2)', 'Immunology and Genetics', 'Mycophenolate mofetil acts by:', '["Depleting complement","Inhibiting IMP dehydrogenase","Blocking IL-2","Inhibiting MHC expression","Blocking calcineurin"]'::jsonb, 'Inhibiting IMP dehydrogenase', 'MMF inhibits inosine monophosphate dehydrogenase, blocking de novo purine synthesis in lymphocytes.'),
('3864526d-36d9-5e97-bd93-2fa3988b978e'::uuid, 'Pathology (Paper 2)', 'Immunology and Genetics', 'Which immunoglobulin deficiency is most common?', '["IgD deficiency","IgG deficiency","IgE deficiency","IgM deficiency","IgA deficiency"]'::jsonb, 'IgA deficiency', 'Selective IgA deficiency is the most common primary immunodeficiency (1:700).'),
('96d53f20-eaaf-578f-9c5a-704ccafa8873'::uuid, 'Pathology (Paper 2)', 'Immunology and Genetics', 'Which immunodeficiency is associated with ataxia-telangiectasia?', '["IgA deficiency and T cell dysfunction","Neutrophil defect","NK cell deficiency","B cell deficiency","Complement deficiency"]'::jsonb, 'IgA deficiency and T cell dysfunction', 'Ataxia-telangiectasia causes IgA deficiency, T cell dysfunction, and cerebellar ataxia.'),
('d1ffebcc-1582-5e4b-8e6f-6f88c59b6eaa'::uuid, 'Pathology (Paper 2)', 'Immunology and Genetics', 'Chronic granulomatous disease (CGD) results from:', '["T cell deficiency","NK cell deficiency","Complement deficiency","B cell deficiency","NADPH oxidase defect in phagocytes"]'::jsonb, 'NADPH oxidase defect in phagocytes', 'CGD results from defective NADPH oxidase, preventing respiratory burst and killing of catalase-positive organisms.'),
('0a72241a-19b8-56aa-aa81-aa7ac13ee6fc'::uuid, 'Pathology (Paper 2)', 'Immunology and Genetics', 'Which infection is typical of CGD?', '["Pneumococcal pneumonia clinical presentation","Giardiasis clinical presentation","Invasive aspergillosis clinical presentation","Viral infections clinical presentation","Staphylococcal abscesses and Catalase-positive infections"]'::jsonb, 'Staphylococcal abscesses and Catalase-positive infections', 'CGD patients get recurrent infections with staphylococci, Serratia, and Aspergillus.'),
('dfd1a806-d1db-54c0-9925-992f98bf72d4'::uuid, 'Pathology (Paper 2)', 'Immunology and Genetics', 'Leukocyte adhesion deficiency (LAD) results from:', '["T cell deficiency","Defective antibodies","Defective integrins","Defective NADPH oxidase","Complement deficiency"]'::jsonb, 'Defective integrins', 'LAD type I results from CD18 (beta-2 integrin) deficiency, impairing leukocyte adhesion and migration.'),
('69519a06-a693-579d-be3f-33945be676c7'::uuid, 'Pathology (Paper 2)', 'Immunology and Genetics', 'Which infection is characteristic of LAD?', '["Viral infections clinical presentation","Parasitic infections clinical presentation","Recurrent bacterial infections without pus","Fungal infections clinical presentation","Prion diseases clinical presentation"]'::jsonb, 'Recurrent bacterial infections without pus', 'LAD presents with delayed wound healing, recurrent infections, and absence of pus (no neutrophil migration).'),
('c50533e5-aebb-5f7a-8345-da9f0e6e147f'::uuid, 'Pathology (Paper 2)', 'Immunology and Genetics', 'X-linked agammaglobulinemia (Bruton) results from:', '["Phagocyte defect","B cell maturation defect","MHC deficiency","Complement deficiency","T cell defect"]'::jsonb, 'B cell maturation defect', 'Bruton agammaglobulinemia is caused by BTK (Bruton tyrosine kinase) mutation, blocking B cell development.'),
('05e1516a-a14f-515c-acfa-a9a78c8d66f3'::uuid, 'Pathology (Paper 2)', 'Immunology and Genetics', 'Which immunoglobulin is absent in Bruton agammaglobulinemia?', '["IgG only","All immunoglobulins","IgA only","IgE only","IgM only"]'::jsonb, 'All immunoglobulins', 'All immunoglobulins are severely decreased in Bruton disease. Patients present after 6 months of age.'),
('1ba45940-4e9f-5988-a2fb-7ad69f88325f'::uuid, 'Pathology (Paper 2)', 'Immunology and Genetics', 'Severe combined immunodeficiency (SCID) involves:', '["Only NK cells","Only B cells","Both T and B cell deficiency","Only T cells","Only phagocytes"]'::jsonb, 'Both T and B cell deficiency', 'SCID involves defective T and B cell (and often NK cell) function, requiring early bone marrow transplant.'),
('0857c8ce-a9d5-5da1-8fb8-f09bbdda9351'::uuid, 'Pathology (Paper 2)', 'Immunology and Genetics', 'Adenosine deaminase (ADA) deficiency causes which immunodeficiency?', '["DiGeorge syndrome","SCID","LAD","CGD","Bruton disease"]'::jsonb, 'SCID', 'ADA deficiency causes SCID due to accumulation of toxic purine metabolites killing lymphocytes.'),
('f554df63-e635-563a-b542-17766ad980e7'::uuid, 'Pathology (Paper 2)', 'Immunology and Genetics', 'DiGeorge syndrome results from:', '["BTK mutation clinical presentation","22q11.2 deletion causing thymic aplasia","NADPH oxidase defect clinical presentation","CD18 deficiency clinical presentation","ADA deficiency clinical presentation"]'::jsonb, '22q11.2 deletion causing thymic aplasia', 'DiGeorge syndrome causes T cell deficiency (thymic aplasia), cardiac defects, and hypoparathyroidism.'),
('27fc2104-6e1b-5bfb-a4e6-f96b46e797b8'::uuid, 'Pathology (Paper 2)', 'Immunology and Genetics', 'Which immunodeficiency is associated with eczema and thrombocytopenia?', '["Bruton disease","Ataxia-telangiectasia","DiGeorge syndrome","CGD","Wiskott-Aldrich syndrome"]'::jsonb, 'Wiskott-Aldrich syndrome', 'WAS (X-linked) presents with eczema, thrombocytopenia with small platelets, and recurrent infections.'),
('aaf9f0eb-e56f-5a9c-9282-6a09910c93f6'::uuid, 'Pathology (Paper 2)', 'Immunology and Genetics', 'Hyper-IgE (Job) syndrome presents with:', '["B cell deficiency clinical presentation","High IgE, eczema, and recurrent staphylococcal abscesses","Low IgE clinical presentation","Complement deficiency clinical presentation","T cell deficiency clinical presentation"]'::jsonb, 'High IgE, eczema, and recurrent staphylococcal abscesses', 'Job syndrome has markedly elevated IgE, eczema, and cold abscesses (''Job syndrome'').'),
('11edfbec-1aa1-56d8-86a3-7c48b0aa507c'::uuid, 'Pathology (Paper 2)', 'Immunology and Genetics', 'Which immunodeficiency is treated with IVIG?', '["CGD","Wiskott-Aldrich syndrome","LAD","Antibody deficiencies","DiGeorge syndrome"]'::jsonb, 'Antibody deficiencies', 'IVIG replacement therapy is used for antibody deficiencies like Bruton and CVID.'),
('086ae4e4-7ce0-514f-a063-f17750975a4c'::uuid, 'Pathology (Paper 2)', 'Immunology and Genetics', 'Which vaccine is contraindicated in SCID?', '["All live vaccines","DTaP only","Hepatitis B only","Tetanus only","Inactivated polio only"]'::jsonb, 'All live vaccines', 'Live attenuated vaccines (MMR, varicella, BCG, oral polio) are contraindicated in SCID.'),
('41e27df9-520c-5d88-a840-ce1a53fab0a3'::uuid, 'Pathology (Paper 2)', 'Immunology and Genetics', 'What is the primary defect in autoimmune diseases?', '["Complement deficiency","Phagocyte defect","MHC deficiency","Loss of self-tolerance","Immunoglobulin deficiency"]'::jsonb, 'Loss of self-tolerance', 'Autoimmune diseases result from loss of self-tolerance, leading to immune attack on self-tissues.'),
('64b98eff-eda0-5f39-a3c8-0a34d3ce15e7'::uuid, 'Pathology (Paper 2)', 'Immunology and Genetics', 'Which HLA type is strongly associated with ankylosing spondylitis?', '["HLA-A1","HLA-DR2","HLA-DR3","HLA-B27","HLA-DR4"]'::jsonb, 'HLA-B27', 'HLA-B27 is present in >90% of patients with ankylosing spondylitis.'),
('91e043be-56eb-56c0-9f21-de640bbf0326'::uuid, 'Pathology (Paper 2)', 'Immunology and Genetics', 'HLA-DR4 is associated with which autoimmune disease?', '["SLE","Rheumatoid arthritis","Ankylosing spondylitis","Multiple sclerosis","Type 1 diabetes"]'::jsonb, 'Rheumatoid arthritis', 'HLA-DR4 is associated with rheumatoid arthritis and type 1 diabetes.'),
('df50bb92-70da-5d1c-9966-a8d6cda09a59'::uuid, 'Pathology (Paper 2)', 'Immunology and Genetics', 'HLA-DR2 is associated with which autoimmune disease?', '["Multiple sclerosis","Hashimoto thyroiditis","Ankylosing spondylitis","Rheumatoid arthritis","Goodpasture syndrome"]'::jsonb, 'Multiple sclerosis', 'HLA-DR2 (DRB1*1501) is strongly associated with multiple sclerosis.'),
('35a2fbf7-41c7-5a58-8b25-eac742338fa2'::uuid, 'Pathology (Paper 2)', 'Immunology and Genetics', 'Which test is used to detect ANA (antinuclear antibodies)?', '["Western blot clinical presentation","Immunohistochemistry clinical presentation","Indirect immunofluorescence on HEp-2 cells","PCR clinical presentation","ELISA clinical presentation"]'::jsonb, 'Indirect immunofluorescence on HEp-2 cells', 'Indirect immunofluorescence on HEp-2 cells is the gold standard for ANA detection.'),
('5e17af7b-af2a-5a22-a8ca-d1ca4970b20f'::uuid, 'Pathology (Paper 2)', 'Immunology and Genetics', 'Which autoantibodies are specific for SLE?', '["Anti-SSA/SSB","Anti-acetylcholine receptor","Anti-CCP","Anti-MPO","Anti-dsDNA, Anti-Smith"]'::jsonb, 'Anti-dsDNA, Anti-Smith', 'Anti-dsDNA and anti-Smith are highly specific for SLE. Anti-dsDNA correlates with disease activity.'),
('7a2fa05a-3610-5919-a687-1872d2a60d07'::uuid, 'Pathology (Paper 2)', 'Immunology and Genetics', 'Which autoantibody is associated with drug-induced lupus?', '["Anti-dsDNA","Anti-La/SSB","Anti-histone","Anti-Smith","Anti-Ro/SSA"]'::jsonb, 'Anti-histone', 'Anti-histone antibodies are characteristic of drug-induced lupus (e.g., procainamide, hydralazine).'),
('04cde31d-af59-5ac9-b48b-b4c07271eb94'::uuid, 'Pathology (Paper 2)', 'Immunology and Genetics', 'Which autoantibodies are associated with Sjogren syndrome?', '["Anti-Ro (SSA) and Anti-La","Anti-dsDNA","Anti-Jo-1","Anti-CCP","Anti-Scl-70"]'::jsonb, 'Anti-Ro (SSA) and Anti-La', 'Anti-Ro/SSA and Anti-La/SSB are specific for Sjogren syndrome.'),
('92179b8e-150f-58b3-947a-f563d00fb451'::uuid, 'Pathology (Paper 2)', 'Immunology and Genetics', 'Which autoantibody is specific for systemic sclerosis?', '["Anti-dsDNA","Anti-CCP","Anti-Scl-70","Anti-La","Anti-Ro"]'::jsonb, 'Anti-Scl-70', 'Anti-Scl-70 is specific for diffuse systemic sclerosis and associated with pulmonary fibrosis.'),
('8d4267b8-aff6-5000-b0d9-a2f4fa91948d'::uuid, 'Pathology (Paper 2)', 'Immunology and Genetics', 'Which autoantibody is associated with CREST syndrome?', '["Anti-PR3","Anti-Jo-1","Anti-MPO","Anti-Scl-70","Anti-centromere"]'::jsonb, 'Anti-centromere', 'Anti-centromere antibody is specific for CREST variant of limited systemic sclerosis.'),
('c009db30-1ad8-5498-9572-fe07d10410b8'::uuid, 'Pathology (Paper 2)', 'Immunology and Genetics', 'Which autoantibody is specific for dermatomyositis?', '["Anti-Scl-70","Anti-MPO","Anti-Ro","Anti-Jo-1","Anti-PR3"]'::jsonb, 'Anti-Jo-1', 'Anti-Jo-1 is associated with dermatomyositis and interstitial lung disease (antisynthetase syndrome).'),
('98fd76c8-bf0f-581b-af86-ffe5148aad31'::uuid, 'Pathology (Paper 2)', 'Immunology and Genetics', 'ANCA (antineutrophil cytoplasmic antibody) is associated with:', '["Sjogren syndrome","Scleroderma","Rheumatoid arthritis","Vasculitis","SLE"]'::jsonb, 'Vasculitis', 'ANCA is a marker for small vessel vasculitis: GPA (c-ANCA/PR3) and MPA (p-ANCA/MPO).'),
('dbcca18f-12e3-57ab-85e0-02392183c432'::uuid, 'Pathology (Paper 2)', 'Immunology and Genetics', 'c-ANCA (cytoplasmic) targets which antigen?', '["Proteinase 3","Lactoferrin","Cathepsin G","BPI","Myeloperoxidase"]'::jsonb, 'Proteinase 3', 'c-ANCA targets PR3 and is specific for granulomatosis with polyangiitis (Wegener).'),
('71df9aa7-d79b-53b7-8060-3fd64eb274fb'::uuid, 'Pathology (Paper 2)', 'Immunology and Genetics', 'p-ANCA (perinuclear) targets which antigen?', '["Cathepsin G","Elastase","Lactoferrin","Proteinase 3","Myeloperoxidase"]'::jsonb, 'Myeloperoxidase', 'p-ANCA targets MPO and is associated with microscopic polyangiitis and eosinophilic GPA.'),
('c41eb6ca-dab5-5b42-8217-f4cf9f13ea17'::uuid, 'Pathology (Paper 2)', 'Immunology and Genetics', 'Anti-glomerular basement membrane (GBM) antibody causes:', '["IgA nephropathy","Goodpasture syndrome","GPA","SLE","MPA"]'::jsonb, 'Goodpasture syndrome', 'Anti-GBM antibodies cause Goodpasture syndrome with rapidly progressive glomerulonephritis and lung hemorrhage.'),
('038aca20-a5d5-5439-93f6-bc0a9286f609'::uuid, 'Pathology (Paper 2)', 'Immunology and Genetics', 'Anti-acetylcholine receptor antibodies cause:', '["ALS","Lambert-Eaton syndrome","Myasthenia gravis","Guillain-Barre syndrome","Multiple sclerosis"]'::jsonb, 'Myasthenia gravis', 'Anti-AChR antibodies block neuromuscular transmission causing myasthenia gravis.'),
('476daefb-0435-564d-8f38-a62ecd537547'::uuid, 'Pathology (Paper 2)', 'Immunology and Genetics', 'Anti-TSH receptor antibodies cause:', '["Pernicious anemia","Addison disease","Graves disease","Type 1 diabetes","Hashimoto thyroiditis"]'::jsonb, 'Graves disease', 'TSI (thyroid-stimulating immunoglobulins) activate TSH receptors causing Graves disease.'),
('c339082a-0153-591b-969e-c4a4ea0fcbfb'::uuid, 'Pathology (Paper 2)', 'Immunology and Genetics', 'Anti-intrinsic factor antibodies cause:', '["Iron deficiency anemia","Sickle cell disease","Pernicious anemia","Aplastic anemia","Hemolytic anemia"]'::jsonb, 'Pernicious anemia', 'Anti-intrinsic factor antibodies block vitamin B12 absorption causing pernicious anemia.'),
('c9a723d4-28ba-5efc-bdb8-9bb49bd2aafa'::uuid, 'Pathology (Paper 2)', 'Immunology and Genetics', 'Anti-transglutaminase antibodies are associated with:', '["Celiac disease","Crohn disease","Whipple disease","Ulcerative colitis","Irritable bowel syndrome"]'::jsonb, 'Celiac disease', 'Anti-tissue transglutaminase (tTG) IgA is highly specific for celiac disease.'),
('ef8d9b3d-bb8f-5b5d-b7d6-2c2957982f76'::uuid, 'Pathology (Paper 2)', 'Immunology and Genetics', 'Anti-mitochondrial antibodies (AMA) are associated with:', '["Autoimmune hepatitis","NAFLD","Primary biliary cholangitis","Primary sclerosing cholangitis","Alcoholic liver disease"]'::jsonb, 'Primary biliary cholangitis', 'AMA (anti-M2) is >95% specific for primary biliary cholangitis.'),
('421d2e7c-da19-5659-86db-263df246b8f1'::uuid, 'Pathology (Paper 2)', 'Immunology and Genetics', 'Anti-smooth muscle antibodies (ASMA) are associated with:', '["Viral hepatitis","Alcoholic hepatitis","PSC","Autoimmune hepatitis type 1","PBC"]'::jsonb, 'Autoimmune hepatitis type 1', 'ASMA (anti-actin) is characteristic of autoimmune hepatitis type 1.'),
('d4df66e6-67c6-502c-a7fd-7e8e8c92913d'::uuid, 'Pathology (Paper 2)', 'Immunology and Genetics', 'Anti-LKM1 antibodies are associated with:', '["Drug-induced hepatitis","PSC","Viral hepatitis","PBC","Autoimmune hepatitis type 2"]'::jsonb, 'Autoimmune hepatitis type 2', 'Anti-LKM1 (liver-kidney microsomal type 1) is characteristic of autoimmune hepatitis type 2 in children.'),
('b7d37c86-e49f-5ea6-9f85-ff66cb3a2b26'::uuid, 'Pathology (Paper 2)', 'Immunology and Genetics', 'Type I hypersensitivity is mediated by:', '["IgE and mast cells","Immune complexes","NK cells","T cells","IgG and complement"]'::jsonb, 'IgE and mast cells', 'Type I (immediate) hypersensitivity is mediated by IgE cross-linking on mast cells releasing histamine.'),
('eb6e3f81-f5fc-5f15-bd8a-23c5b30eee2b'::uuid, 'Pathology (Paper 2)', 'Immunology and Genetics', 'Which type of hypersensitivity is involved in anaphylaxis?', '["Type III","Type IV","Type V","Type I","Type II"]'::jsonb, 'Type I', 'Anaphylaxis is a systemic Type I hypersensitivity reaction.'),
('72e94f72-e639-5c82-98cd-aa172b064326'::uuid, 'Pathology (Paper 2)', 'Immunology and Genetics', 'Type II hypersensitivity is mediated by:', '["Immune complexes clinical presentation","Antibodies (IgG/IgM) against cell surface antigens","T cells clinical presentation","IgE and mast cells clinical presentation","Cytokines clinical presentation"]'::jsonb, 'Antibodies (IgG/IgM) against cell surface antigens', 'Type II (cytotoxic) hypersensitivity involves antibodies against cell surface antigens causing cell lysis.'),
('b3230bf4-c1e8-57f2-9a00-92c369106d67'::uuid, 'Pathology (Paper 2)', 'Immunology and Genetics', 'Which disease is an example of Type II hypersensitivity?', '["Contact dermatitis","Allergic rhinitis","TB test reaction","Autoimmune hemolytic anemia","Serum sickness"]'::jsonb, 'Autoimmune hemolytic anemia', 'AIHA, Goodpasture syndrome, and myasthenia gravis are Type II hypersensitivity.'),
('df85362a-6d69-5af7-9c7e-b543cb3c1a39'::uuid, 'Pathology (Paper 2)', 'Immunology and Genetics', 'Type III hypersensitivity is mediated by:', '["Antibodies against cell antigens","Cytotoxic T cells","IgE and mast cells","Immune complex deposition","T cells"]'::jsonb, 'Immune complex deposition', 'Type III (immune complex) hypersensitivity involves deposition of antigen-antibody complexes.'),
('ac912aeb-3989-560b-92da-5d4d81161cfb'::uuid, 'Pathology (Paper 2)', 'Immunology and Genetics', 'Which disease is an example of Type III hypersensitivity?', '["Contact dermatitis","Serum sickness and SLE","Allergic rhinitis","MS","Type 1 diabetes"]'::jsonb, 'Serum sickness and SLE', 'Serum sickness, SLE, and post-streptococcal glomerulonephritis are Type III reactions.'),
('3736d1a8-accf-59a5-8afa-7fd8b548cd45'::uuid, 'Pathology (Paper 2)', 'Immunology and Genetics', 'Type IV hypersensitivity is mediated by:', '["T cells","Immune complexes","IgE","Complement","IgG"]'::jsonb, 'T cells', 'Type IV (delayed) hypersensitivity is mediated by sensitized T cells, not antibodies.'),
('7a27e97a-8069-5d07-b719-bd1b2dbd5a96'::uuid, 'Pathology (Paper 2)', 'Immunology and Genetics', 'Which test is an example of Type IV hypersensitivity?', '["Coombs test","Rheumatoid factor test","PPD (Mantoux) test","Allergy skin prick test","ANA test"]'::jsonb, 'PPD (Mantoux) test', 'The Mantoux (TB skin) test is Type IV hypersensitivity mediated by memory T cells.'),
('d2b4ca88-2ec1-55c5-bbb2-22ac0029c3b3'::uuid, 'Pathology (Paper 2)', 'Immunology and Genetics', 'Contact dermatitis to poison ivy is which type of hypersensitivity?', '["Type I","Type II","Type V","Type IV","Type III"]'::jsonb, 'Type IV', 'Contact dermatitis is Type IV delayed hypersensitivity mediated by T cells.'),
('6d8bf582-3d32-5738-afe2-c35e6ddd8756'::uuid, 'Pathology (Paper 2)', 'Immunology and Genetics', 'Graft rejection is primarily mediated by:', '["B cells","NK cells","Antibodies","Complement","T cells"]'::jsonb, 'T cells', 'Acute graft rejection is mainly T cell-mediated, especially CD8+ CTLs killing graft cells.'),
('e9db774b-fe34-5207-856f-425f465eeb88'::uuid, 'Pathology (Paper 2)', 'Immunology and Genetics', 'Hyperacute graft rejection occurs due to:', '["NK cell activation clinical presentation","Complement deficiency clinical presentation","T cell response clinical presentation","Pre-existing antibodies against donor antigens","Cytokine storm clinical presentation"]'::jsonb, 'Pre-existing antibodies against donor antigens', 'Hyperacute rejection occurs within minutes to hours due to pre-formed antibodies (ABO or HLA).'),
('8a980169-e141-5bb1-b961-0ad5c7ed32d6'::uuid, 'Pathology (Paper 2)', 'Immunology and Genetics', 'Acute graft rejection typically occurs:', '["Within days to weeks","Within minutes","Months to years","Decades","After 5 years"]'::jsonb, 'Within days to weeks', 'Acute rejection occurs days to weeks after transplantation, mainly T cell-mediated.'),
('1a267149-3882-5c36-85a0-7b8ffd3c061f'::uuid, 'Pathology (Paper 2)', 'Immunology and Genetics', 'Chronic graft rejection is characterized by:', '["Acute inflammation","Arteriosclerosis and fibrosis","Hemorrhage","Neutrophil infiltration","Edema"]'::jsonb, 'Arteriosclerosis and fibrosis', 'Chronic rejection shows graft arteriosclerosis, fibrosis, and parenchymal atrophy.'),
('d0867def-9048-52ed-9f4a-c023f568f69e'::uuid, 'Pathology (Paper 2)', 'Immunology and Genetics', 'Graft-versus-host disease (GVHD) occurs in:', '["Bone marrow transplant with immunocompetent donor cells","Skin graft clinical presentation","Corneal transplant clinical presentation","Blood transfusion clinical presentation","Solid organ transplant clinical presentation"]'::jsonb, 'Bone marrow transplant with immunocompetent donor cells', 'GVHD occurs when donor T cells in bone marrow attack host tissues (skin, liver, GI tract).'),
('2fb854b9-4521-5f2b-9866-a4ce3c3fc42b'::uuid, 'Pathology (Paper 2)', 'Immunology and Genetics', 'Which cells are primarily responsible for GVHD?', '["Recipient T cells","NK cells","Donor T cells","Macrophages","Donor B cells"]'::jsonb, 'Donor T cells', 'Mature donor T cells recognize host tissues as foreign and cause GVHD.'),
('2a2268fb-d8cf-552d-ab19-98f507265e6f'::uuid, 'Pathology (Paper 2)', 'Immunology and Genetics', 'Which immunosuppressant is a calcineurin inhibitor?', '["Sirolimus","Azathioprine","Mycophenolate mofetil","Cyclosporine A","Corticosteroids"]'::jsonb, 'Cyclosporine A', 'Cyclosporine and tacrolimus are calcineurin inhibitors blocking IL-2 transcription.'),
('7db6e6a7-82de-5d02-849d-9f6664e0316b'::uuid, 'Pathology (Paper 2)', 'Immunology and Genetics', 'Azathioprine acts by:', '["Blocking calcineurin","Depleting T cells","Inhibiting mTOR","Inhibiting DNA synthesis","Blocking IL-2"]'::jsonb, 'Inhibiting DNA synthesis', 'Azathioprine is metabolized to 6-mercaptopurine, inhibiting purine synthesis in lymphocytes.'),
('2a07fdb7-796e-5251-a503-7e8a3ca51348'::uuid, 'Pathology (Paper 2)', 'Immunology and Genetics', 'Monoclonal antibodies used as immunosuppressants include:', '["Tacrolimus","Cyclosporine","Prednisolone","Mycophenolate","Basiliximab"]'::jsonb, 'Basiliximab', 'Basiliximab and daclizumab are anti-CD25 monoclonal antibodies blocking IL-2 receptor.'),
('788e5c3c-370b-56ba-ac4a-c17bf1afa6f6'::uuid, 'Pathology (Paper 2)', 'Immunology and Genetics', 'Rituximab is a monoclonal antibody against:', '["CD20 on B cells","CD52","CD3 on T cells","CD25 on activated T cells","TNF-alpha"]'::jsonb, 'CD20 on B cells', 'Rituximab (anti-CD20) depletes B cells, used in lymphoma and autoimmune diseases.'),
('5a6b1cd8-80c0-565b-980c-f39cf4ffe85a'::uuid, 'Pathology (Paper 2)', 'Immunology and Genetics', 'Infliximab is a monoclonal antibody against:', '["CD20","IL-1","TNF-alpha","CD25","IL-6"]'::jsonb, 'TNF-alpha', 'Infliximab (anti-TNF-alpha) is used for rheumatoid arthritis, IBD, and ankylosing spondylitis.'),
('c16383f3-50ca-5b83-8943-e59dd1f3744e'::uuid, 'Pathology (Paper 2)', 'Immunology and Genetics', 'Tocilizumab is a monoclonal antibody against:', '["IL-6 receptor","IL-1","CD25","TNF-alpha","CD20"]'::jsonb, 'IL-6 receptor', 'Tocilizumab blocks IL-6 receptor, used in rheumatoid arthritis and cytokine release syndrome.'),
('9b48bbfc-ba2e-5b34-a559-48e0f911b21b'::uuid, 'Pathology (Paper 2)', 'Immunology and Genetics', 'Anakinra is an IL-1 receptor antagonist used in:', '["Rheumatoid arthritis and CAPS","Multiple sclerosis","SLE","Psoriasis","Type 1 diabetes"]'::jsonb, 'Rheumatoid arthritis and CAPS', 'Anakinra blocks IL-1 signaling, used in RA and cryopyrin-associated periodic syndromes.'),
('547c948d-2ed8-5686-a363-938c56b79bfa'::uuid, 'Pathology (Paper 2)', 'Immunology and Genetics', 'IFN-gamma is produced mainly by:', '["Th17 cells","B cells","Th1 cells and NK cells","Th2 cells","Macrophages"]'::jsonb, 'Th1 cells and NK cells', 'IFN-gamma is mainly produced by Th1 cells and NK cells, activating macrophages.'),
('748d7236-f928-55b8-9f56-3ea2957a3bc0'::uuid, 'Pathology (Paper 2)', 'Immunology and Genetics', 'IL-10 is an anti-inflammatory cytokine produced by:', '["Cytotoxic T cells","Th17 cells","Th2 cells","Macrophages and Treg cells","Th1 cells"]'::jsonb, 'Macrophages and Treg cells', 'IL-10 is produced by Treg cells and macrophages, suppressing immune responses.'),
('046b9ff9-6930-5b2d-90eb-82a43b615497'::uuid, 'Pathology (Paper 2)', 'Immunology and Genetics', 'Which cytokine is essential for NK cell activation?', '["IL-2","IL-12","IL-10","IL-4","TGF-beta"]'::jsonb, 'IL-12', 'IL-12 promotes NK cell activation and IFN-gamma production.'),
('d4eb8707-3fc0-5520-8080-c2c6005e6de6'::uuid, 'Pathology (Paper 2)', 'Immunology and Genetics', 'Which cytokine induces fever and acute phase response?', '["IL-17","TGF-beta","IL-1 and IL-6","IL-4","IL-10"]'::jsonb, 'IL-1 and IL-6', 'IL-1 and IL-6 are pyrogenic cytokines inducing fever and hepatic acute phase protein synthesis.'),
('2576c8f7-a2dc-5927-8049-2ed834079c8e'::uuid, 'Pathology (Paper 2)', 'Immunology and Genetics', 'Which cytokine is the main chemotactic factor for neutrophils (CXCL8)?', '["IL-6","IL-2","IL-1","IL-8","MCP-1"]'::jsonb, 'IL-8', 'IL-8 (CXCL8) is a potent chemoattractant for neutrophils.'),
('67e1cfcd-f03a-5947-9ea9-fe7add0aad1a'::uuid, 'Pathology (Paper 2)', 'Immunology and Genetics', 'Which chemokine attracts monocytes?', '["CXCL10","CCL2","CCL5","CXCL12","CXCL8"]'::jsonb, 'CCL2', 'MCP-1 (CCL2) is the main monocyte chemoattractant.'),
('97f30466-56a6-52e7-984e-a399936612ad'::uuid, 'Pathology (Paper 2)', 'Immunology and Genetics', 'Which interferon has antiviral activity?', '["IFN-gamma only","None","IFN-beta only","IFN-alpha only","IFN-alpha and IFN-beta"]'::jsonb, 'IFN-alpha and IFN-beta', 'Type I IFNs (alpha, beta) have potent antiviral activity. IFN-gamma has immunomodulatory effects.'),
('54901868-19a3-5239-9c0e-c8e8a80b90f5'::uuid, 'Pathology (Paper 2)', 'Immunology and Genetics', 'The JAK-STAT pathway is used by which cytokine receptors?', '["Only TNF receptor","Only IL-1 receptor","Only chemokine receptors","Only TGF-beta receptor","All cytokine receptors"]'::jsonb, 'All cytokine receptors', 'Most cytokine receptors use the JAK-STAT signaling pathway for signal transduction.'),
('aef1ffeb-aea2-5af4-9fb0-14070ca260e6'::uuid, 'Pathology (Paper 2)', 'Immunology and Genetics', 'Which cell recognizes MHC class I on target cells?', '["Macrophages","B cells","NK cells","CD8+ T cells","CD4+ T cells"]'::jsonb, 'CD8+ T cells', 'CD8+ cytotoxic T cells recognize antigen on MHC class I of target cells.'),
('e7ea73c8-fbf6-5bbb-bb11-a95dd5dc55d4'::uuid, 'Pathology (Paper 2)', 'Immunology and Genetics', 'Which cell recognizes MHC class I in the absence of peptide?', '["NK cells via KIRs","B cells","CD8+ T cells","Dendritic cells","CD4+ T cells"]'::jsonb, 'NK cells via KIRs', 'NK cells use KIRs (killer immunoglobulin-like receptors) to detect missing self-MHC class I.'),
('1036db44-b392-5b6b-b582-60b5a764e3e0'::uuid, 'Pathology (Paper 2)', 'Immunology and Genetics', 'The most important function of opsonization is:', '["Neutralization of toxins","Agglutination","Chemotaxis","Enhanced phagocytosis","Complement activation"]'::jsonb, 'Enhanced phagocytosis', 'Opsonins (IgG, C3b) coat pathogens for recognition and uptake by phagocyte Fc and complement receptors.'),
